ReplacementChunks.ReplacementContent:
import { useNotebooks } from "@/hooks/useNotebooks";
import { useIsMobile } from "@/hooks/use-mobile";
import NotebookFloatingButton from "@/components/NotebookFloatingButton";
import NotebookWorkspace from "@/components/NotebookWorkspace";
import NotebookSheet from "@/components/NotebookSheet";

ReplacementChunks.TargetContent:
import { useNotebooks } from "@/hooks/useNotebooks";
import NotebookFloatingButton from "@/components/NotebookFloatingButton";
import NotebookWorkspace from "@/components/NotebookWorkspace";
import NotebookSheet from "@/components/NotebookSheet";

ReplacementChunks.ReplacementContent:
  {/* Desktop sidebar â€” apenas montado no React quando isMobile=false */}
  {isNotebookOpen && selectedBook && !isMobile && (
    <NotebookWorkspace
      notebooks={notebooks}
      allNotebooks={allNotebooks}
      bookId={selectedBook.id}
      chapter={chapterNumber}
      version={selectedVersion}
      bookName={selectedBook.name}
      saveStatus={notebookSaveStatus}
      syncError={notebookSyncError}
      onSave={saveNotebook}
      onDelete={deleteNotebook}
      onClose={() => setIsNotebookOpen(false)}
      getLocalDraft={getNotebookLocalDraft}
      getNewLocalDraft={getNotebookNewLocalDraft}
    />
  )}

  {/* Mobile bottom sheet â€” apenas montado no React quando isMobile=true */}
  {selectedBook && isMobile && (
    <NotebookSheet
      open={isNotebookOpen}
      onOpenChange={setIsNotebookOpen}
      notebooks={notebooks}
      bookId={selectedBook.id}
      chapter={chapterNumber}
      version={selectedVersion}
      bookName={selectedBook.name}
      saveStatus={notebookSaveStatus}
      syncError={notebookSyncError}
      onSave={saveNotebook}
      onDelete={deleteNotebook}
      getLocalDraft={getNotebookLocalDraft}
      getNewLocalDraft={getNotebookNewLocalDraft}
    />
  )}
</div>

ReplacementChunks.TargetContent:
  {/* Desktop sidebar */}
  {isNotebookOpen && selectedBook && (
    <div className="hidden md:block">
      <NotebookWorkspace
        notebooks={notebooks}
        allNotebooks={allNotebooks}
        bookId={selectedBook.id}
        chapter={chapterNumber}
        version={selectedVersion}
        bookName={selectedBook.name}
        saveStatus={notebookSaveStatus}
        syncError={notebookSyncError}
        onSave={saveNotebook}
        onDelete={deleteNotebook}
        onClose={() => setIsNotebookOpen(false)}
        getLocalDraft={getNotebookLocalDraft}
        getNewLocalDraft={getNotebookNewLocalDraft}
      />
    </div>
  )}

  {/* Mobile bottom sheet */}
  {selectedBook && (
    <div className="block md:hidden">
      <NotebookSheet
        open={isNotebookOpen}
        onOpenChange={setIsNotebookOpen}
        notebooks={notebooks}
        bookId={selectedBook.id}
        chapter={chapterNumber}
        version={selectedVersion}
        bookName={selectedBook.name}
        saveStatus={notebookSaveStatus}
        syncError={notebookSyncError}
        onSave={saveNotebook}
        onDelete={deleteNotebook}
        getLocalDraft={getNotebookLocalDraft}
        getNewLocalDraft={getNotebookNewLocalDraft}
      />
    </div>
  )}
</div>
